local A={};local function good(n)return type(n)=="number"and n==n and n%1==0 and n>=0 end
local function call(o,m,...)if not o or type(o[m])~="function"then error("missing native method: "..m)end;return o[m](o,...)end
local function door(d)return type(instanceof)=="function"and(instanceof(d,"IsoDoor")or(instanceof(d,"IsoThumpable")and type(d.isDoor)=="function"and d:isDoor()))end
function A.createForBuilding(b)local ok,r=pcall(function()local d=call(b,"getDef");local id=call(d,"getKeyId");if not good(id)then error("building has no existing key id")end;if not InventoryItemFactory or type(InventoryItemFactory.CreateItem)~="function"then error("InventoryItemFactory unavailable")end;local k=InventoryItemFactory.CreateItem("Base.Key1");if not k or call(k,"getFullType")~="Base.Key1"then error("factory did not create Base.Key1")end;if type(k.getContainer)~="function"or type(k.getWorldItem)~="function"then error("cannot establish detached item")end;if k:getContainer()~=nil then error("factory item attached")end;if k:getWorldItem()~=nil then error("factory item in world")end;call(k,"setKeyId",id);if call(k,"getKeyId")~=id then error("key assignment failed")end;return k end);if not ok then return nil,r end;return r,"created-detached"end
function A.observeInteractedMatch(c)local ok,r=pcall(function()if type(c)~="table"or c.interaction~="door"or type(c.interactionToken)~="string"or c.interactionToken==""then error("not-interacted")end;local d,k,p=c.interactedDoor,c.heldKey,c.player;if not door(d)then error("not-door")end;local i=call(p,"getInventory");local held=(type(k.getOutermostContainer)=="function"and k:getOutermostContainer()==i)or(type(i.contains)=="function"and i:contains(k));if not held then error("key-not-held")end;local ki,di=call(k,"getKeyId"),call(d,"getKeyId");if not good(ki)or not good(di)or ki~=di then error("key-mismatch")end;local building=call(call(d,"getSquare"),"getBuilding");if not building and type(d.getOppositeSquare)=="function"then building=call(call(d,"getOppositeSquare"),"getBuilding")end;local def=call(building,"getDef");if call(def,"getKeyId")~=di then error("building-key-mismatch")end;local b=call(def,"getIDString");if b~=c.buildingId or type(b)~="string"or b==""or type(c.doorId)~="string"or c.doorId==""or type(c.keyToken)~="string"or c.keyToken==""or type(c.factId)~="string"or c.factId==""then error("invalid-context")end;return {kind="keyDoorMatch",id=c.factId,keyToken=c.keyToken,keyId=ki,doorId=c.doorId,buildingId=b}end);if not ok then return nil,r end;return r,"matching-key-observed"end
return A
